import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { supabase } from '../services/supabaseClient';

interface OnboardingData {
	role: string;
	weddingStyle: string;
	topPriority?: string[];
	estimatedBudget?: number;
	guestCount?: number;
	weddingDate?: string;
	weddingTime?: string;
	weddingCity?: string;
	weddingState?: string;
	weddingCountry?: string;
	isReligious?: boolean;
	ceremonyType?: string;
	goals?: string;
	wantsBachelorParty?: boolean;
	plannerData?: Record<string, any>;
	[key: string]: any;
}

interface Budget {
	_id: string;
	userId: string;
	title: string;
	totalBudget: number;
	spent: number;
	remaining: number;
	expenses: any[];
	[key: string]: any;
}

interface Registry {
	_id: string;
	userId: string;
	name: string;
	items: any[];
	[key: string]: any;
}

interface User {
	_id: string;
	email: string;
	name?: string;
	isAdmin?: boolean;
	onboardingCompleted?: boolean;
	[key: string]: any;
}

interface AppContextType {
	user: User | null;
	isAuthenticated: boolean;
	isLoading: boolean;
	onboardingData: OnboardingData | null;
	setOnboardingData: (data: OnboardingData) => void;
	saveOnboarding: (data: OnboardingData) => Promise<void>;
	hasCompletedOnboarding: boolean;
	budgets: Budget[];
	fetchBudgets: () => Promise<void>;
	updateBudget: (id: string, data: any) => Promise<void>;
	deleteBudget: (id: string) => Promise<void>;
	registries: Registry[];
	fetchRegistries: () => Promise<void>;
	updateRegistry: (id: string, data: any) => Promise<void>;
	expenses: any[];
	fetchExpenses: (budgetId: string) => Promise<void>;
	addExpense: (budgetId: string, expense: any) => Promise<void>;
	settleExpense: (expenseId: string) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider = ({ children }: { children: React.ReactNode }) => {
	const [user, setUser] = useState<User | null>(null);
	const [isAuthenticated, setIsAuthenticated] = useState(false);
	const [isLoading, setIsLoading] = useState(true);
	const [onboardingData, setOnboardingData] = useState<OnboardingData | null>(null);
	const [hasCompletedOnboarding, setHasCompletedOnboarding] = useState(false);
	const [budgets, setBudgets] = useState<Budget[]>([]);
	const [registries, setRegistries] = useState<Registry[]>([]);
	const [expenses, setExpenses] = useState<any[]>([]);

	const saveOnboarding = useCallback(async (data: OnboardingData) => {
		const user = await supabase.auth.getUser();
		if (!user.data?.user?.id) throw new Error('User not authenticated');
		const onboardingPayload: Record<string, any> = { user_id: user.data.user.id };
		for (const [key, value] of Object.entries(data)) {
			if (Array.isArray(value) || (typeof value === 'object' && value !== null)) {
				onboardingPayload[key] = JSON.stringify(value);
			} else {
				onboardingPayload[key] = value;
			}
		}
		const { data: upserted, error } = await supabase
			.from('onboarding')
			.upsert([onboardingPayload], { onConflict: 'user_id' })
			.select();
		if (error) throw error;
		setOnboardingData(upserted?.[0] || data);
		setHasCompletedOnboarding(true);
	}, []);

	const fetchBudgets = useCallback(async () => {
		const user = await supabase.auth.getUser();
		if (!user.data?.user?.id) return;
		const { data: budgets, error } = await supabase
			.from('budgets')
			.select('*')
			.eq('user_id', user.data.user.id);
		if (!error && budgets) setBudgets(budgets);
	}, []);

	const updateBudget = useCallback(async (id: string, data: any) => {
		const { error } = await supabase
			.from('budgets')
			.update(data)
			.eq('id', id);
		if (error) throw error;
		await fetchBudgets();
	}, [fetchBudgets]);

	const deleteBudget = useCallback(async (id: string) => {
		const { error } = await supabase
			.from('budgets')
			.delete()
			.eq('id', id);
		if (error) throw error;
		await fetchBudgets();
	}, [fetchBudgets]);

	const fetchRegistries = useCallback(async () => {
		const user = await supabase.auth.getUser();
		if (!user.data?.user?.id) return;
		const { data: registries, error } = await supabase
			.from('registries')
			.select('*')
			.eq('user_id', user.data.user.id);
		if (!error && registries) setRegistries(registries);
	}, []);

	const updateRegistry = useCallback(async (id: string, data: any) => {
		const { error } = await supabase
			.from('registries')
			.update(data)
			.eq('id', id);
		if (error) throw error;
		await fetchRegistries();
	}, [fetchRegistries]);

	const fetchExpenses = useCallback(async (budgetId: string) => {
		const { data: expenses, error } = await supabase
			.from('expenses')
			.select('*')
			.eq('budget_id', budgetId);
		if (!error && expenses) setExpenses(expenses);
	}, []);

	const addExpense = useCallback(async (budgetId: string, expense: any) => {
		const { error } = await supabase
			.from('expenses')
			.insert([{ ...expense, budget_id: budgetId }]);
		if (error) throw error;
		await fetchExpenses(budgetId);
	}, [fetchExpenses]);

	const settleExpense = useCallback(async (expenseId: string) => {
		const { error } = await supabase
			.from('expenses')
			.update({ settled: true })
			.eq('id', expenseId);
		if (error) throw error;
		await fetchBudgets();
	}, [fetchBudgets]);

	useEffect(() => {
		const fetchOnboardingStatus = async () => {
			try {
				setIsLoading(true);
				const userRes = await supabase.auth.getUser();
				const userId = userRes.data?.user?.id;
				if (userId && userRes.data.user) {
					setIsAuthenticated(true);
					setUser({ _id: userId, email: userRes.data.user.email || '' });
					const { data: onboardingRows, error } = await supabase
						.from('onboarding')
						.select('*')
						.eq('user_id', userId)
						.maybeSingle();
					if (error) {
						setOnboardingData(null);
						setHasCompletedOnboarding(false);
					} else if (onboardingRows) {
						setOnboardingData(onboardingRows);
						setHasCompletedOnboarding(true);
					} else {
						setOnboardingData(null);
						setHasCompletedOnboarding(false);
					}
				} else {
					setIsAuthenticated(false);
					setUser(null);
					setOnboardingData(null);
					setHasCompletedOnboarding(false);
				}
				setIsLoading(false);
			} catch (err) {
				setIsAuthenticated(false);
				setUser(null);
				setOnboardingData(null);
				setHasCompletedOnboarding(false);
				setIsLoading(false);
			}
		};
		fetchOnboardingStatus();
	}, []);

	const value: AppContextType = {
		user,
		isAuthenticated,
		isLoading,
		onboardingData,
		setOnboardingData,
		saveOnboarding,
		hasCompletedOnboarding,
		budgets,
		fetchBudgets,
		updateBudget,
		deleteBudget,
		registries,
		fetchRegistries,
		updateRegistry,
		expenses,
		fetchExpenses,
		addExpense,
		settleExpense,
	};
	return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useApp = () => {
	const context = useContext(AppContext);
	if (context === undefined) {
		throw new Error('useApp must be used within an AppProvider');
	}
	return context;
};
