import React from 'react'
import ReactDOM from 'react-dom/client'
import App from './App.tsx'
import { ErrorBoundary } from './ErrorBoundary.tsx'
import { AppProvider } from './context/AppContext.tsx'
import './index.css'
import axios from 'axios'

console.log('main.tsx: App starting');

// Check for required environment variables
const missingVars: string[] = [];
if (!import.meta.env.VITE_SUPABASE_URL) missingVars.push('VITE_SUPABASE_URL');
if (!import.meta.env.VITE_SUPABASE_ANON_KEY) missingVars.push('VITE_SUPABASE_ANON_KEY');

if (missingVars.length > 0) {
  const warning = `Missing required environment variables: ${missingVars.join(', ')}`;
  // Show a visible warning in the DOM
  const warnDiv = document.createElement('div');
  warnDiv.style.background = '#fbbf24';
  warnDiv.style.color = '#7c2d12';
  warnDiv.style.padding = '16px';
  warnDiv.style.fontWeight = 'bold';
  warnDiv.style.fontSize = '18px';
  warnDiv.style.textAlign = 'center';
  warnDiv.innerText = warning;
  document.body.prepend(warnDiv);
  console.error(warning);
}

// Set global axios defaults so API calls use the configured backend URL
axios.defaults.baseURL = import.meta.env.VITE_API_URL || '';
axios.defaults.timeout = 30000; // 30s default client-side timeout (allow backend cold-starts)

// Global error handler for debugging
window.addEventListener('error', (e) => {
  console.error('Global error:', e.error);
});

window.addEventListener('unhandledrejection', (e) => {
  console.error('Unhandled rejection:', e.reason);
});


try {
  const root = document.getElementById('root');
  if (!root) {
    throw new Error('Root element not found');
  }
  console.log('main.tsx: ReactDOM.createRoot about to render');
  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <ErrorBoundary>
        <AppProvider>
          <App />
        </AppProvider>
      </ErrorBoundary>
    </React.StrictMode>,
  );
  console.log('main.tsx: ReactDOM.createRoot render complete');
} catch (err) {
  console.error('main.tsx: Top-level error', err);
  const errorDiv = document.createElement('div');
  errorDiv.style.background = '#fee2e2';
  errorDiv.style.color = '#991b1b';
  errorDiv.style.padding = '16px';
  errorDiv.style.fontWeight = 'bold';
  errorDiv.style.fontSize = '18px';
  errorDiv.style.textAlign = 'center';
  errorDiv.innerText = 'Critical error: ' + (err instanceof Error ? err.message : String(err));
  document.body.prepend(errorDiv);
}
